class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        n, m = len(grid), len(grid[0])
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))  # DR, DL, UL, UR
        nxt = (2, 2, 0)                              # next value after 0, 1, 2
        ans = 0
        g = grid

        for d in range(4):
            dr, dc = dirs[d]
            odr, odc = dirs[(d + 1) % 4]  # clockwise outgoing direction

            # F[i][j]: longest straight continuation starting at (i,j)
            # in the outgoing direction, counting (i,j).
            F = [[1] * m for _ in range(n)]
            f_rows = range(n - 1, -1, -1) if odr > 0 else range(n)
            f_cols = range(m - 1, -1, -1) if odc > 0 else range(m)

            for i in f_rows:
                gi = g[i]
                Fi = F[i]
                ni = i + odr
                if 0 <= ni < n:
                    gni = g[ni]
                    Fni = F[ni]
                    for j in f_cols:
                        nj = j + odc
                        if 0 <= nj < m and gni[nj] == nxt[gi[j]]:
                            Fi[j] = Fni[nj] + 1

            # B[i][j]: longest valid straight prefix ending at (i,j)
            # in the incoming direction, enforcing that it started with 1.
            B = [[0] * m for _ in range(n)]
            b_rows = range(n) if dr > 0 else range(n - 1, -1, -1)
            b_cols = range(m) if dc > 0 else range(m - 1, -1, -1)

            for i in b_rows:
                gi = g[i]
                Bi = B[i]
                Fi = F[i]
                pi = i - dr

                if 0 <= pi < n:
                    gpi = g[pi]
                    Bpi = B[pi]
                    for j in b_cols:
                        val = gi[j]
                        if val == 1:
                            Bi[j] = 1
                        else:
                            pj = j - dc
                            if 0 <= pj < m:
                                prev_len = Bpi[pj]
                                if prev_len > 0 and val == nxt[gpi[pj]]:
                                    Bi[j] = prev_len + 1

                        blen = Bi[j]
                        if blen > 0:
                            total = blen + Fi[j] - 1
                            if total > ans:
                                ans = total
                else:
                    for j in b_cols:
                        if gi[j] == 1:
                            Bi[j] = 1
                            total = Fi[j]
                            if total > ans:
                                ans = total

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def occurrences(text, pat):
            m = len(pat)
            if m == 0 or m > len(text):
                return []
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            res = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res

        A, B, C = p.split('*')

        if not A and not B and not C:
            return 0

        occA = occurrences(s, A) if A else []
        occB = occurrences(s, B) if B else []
        occC = occurrences(s, C) if C else []

        if A and not occA:
            return -1
        if B and not occB:
            return -1
        if C and not occC:
            return -1

        la, lb, lc = len(A), len(B), len(C)
        INF = 10**18
        ans = INF

        if A and B and C:
            pa = -1
            pc = 0
            for b in occB:
                while pa + 1 < len(occA) and occA[pa + 1] + la <= b:
                    pa += 1
                if pa < 0:
                    continue

                while pc < len(occC) and occC[pc] < b + lb:
                    pc += 1
                if pc == len(occC):
                    continue

                cand = occC[pc] + lc - occA[pa]
                if cand < ans:
                    ans = cand

        elif A and B:
            pa = -1
            for b in occB:
                while pa + 1 < len(occA) and occA[pa + 1] + la <= b:
                    pa += 1
                if pa < 0:
                    continue

                cand = b + lb - occA[pa]
                if cand < ans:
                    ans = cand

        elif A and C:
            pa = -1
            for c in occC:
                while pa + 1 < len(occA) and occA[pa + 1] + la <= c:
                    pa += 1
                if pa < 0:
                    continue

                cand = c + lc - occA[pa]
                if cand < ans:
                    ans = cand

        elif B and C:
            pc = 0
            for b in occB:
                while pc < len(occC) and occC[pc] < b + lb:
                    pc += 1
                if pc == len(occC):
                    continue

                cand = occC[pc] + lc - b
                if cand < ans:
                    ans = cand

        elif A:
            return la
        elif B:
            return lb
        elif C:
            return lc

        return -1 if ans == INF else ans

