import sys
import gc


def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    gc.disable()

    N = int(data[0])
    P = int(data[1])

    H = N // 2
    Emax = H - 1
    total_edges = N * (N - 1) // 2
    D = total_edges - H + 1

    # factorials and inverse factorials modulo P
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % P

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    fact_nm1 = fact[N - 1]

    # Build reachable and feasible BFS-layer states.
    # state: (o, e, p, par)
    # o: total size of odd-distance non-root layers
    # e: total size of even-distance non-root layers
    # p: size of the last layer
    # par: 0 = last layer even (root initially), 1 = last layer odd
    states = []
    idx_map = {}

    def add_state(o, e, p, par):
        key = (o, e, p, par)
        if key not in idx_map:
            idx_map[key] = len(states)
            states.append(key)

    # root
    add_state(0, 0, 1, 0)

    # par = 0, non-root even last layer
    for e in range(1, Emax + 1):
        o_max = H if e == Emax else H - 1
        for o in range(1, o_max + 1):
            if o == 1:
                p_vals = (e,)
            else:
                p_vals = range(1, e + 1)
            for p in p_vals:
                add_state(o, e, p, 0)

    # par = 1, odd last layer
    # e = 0: only one odd layer, so p = o
    for o in range(1, H + 1):
        add_state(o, 0, o, 1)

    # 0 < e < Emax: need at least one previous odd layer, so p <= o-1
    for e in range(1, Emax):
        for o in range(2, H + 1):
            for p in range(1, o):
                add_state(o, e, p, 1)

    # final odd layer: e = Emax, o = H, p < H (unless H=1 handled above)
    if Emax > 0:
        for p in range(1, H):
            add_state(H, Emax, p, 1)

    S = len(states)
    L = H
    stride = L + 1

    # Precompute transitions and weight offsets.
    trans = [[] for _ in range(S)]
    for idx, (o, e, p, par) in enumerate(states):
        if par == 0:
            if o == H and e == Emax:
                continue
            max_a = H - o
            base = p * stride
            for a in range(1, max_a + 1):
                t = idx_map.get((o + a, e, a, 1))
                if t is not None:
                    trans[idx].append((t, base + a))
        else:
            if o == H and e == Emax:
                continue
            max_b = Emax - e
            if max_b <= 0:
                continue
            base = p * stride
            if o == H:
                b = max_b
                t = idx_map.get((H, Emax, b, 0))
                if t is not None:
                    trans[idx].append((t, base + b))
            else:
                for b in range(1, max_b + 1):
                    t = idx_map.get((o, e + b, b, 0))
                    if t is not None:
                        trans[idx].append((t, base + b))

    order = [
        i for i in sorted(range(S), key=lambda i: states[i][0] + states[i][1])
        if trans[i]
    ]
    final_indices = [
        i for i, (o, e, p, par) in enumerate(states)
        if o == H and e == Emax
    ]
    init_idx = idx_map[(0, 0, 1, 0)]

    vals = [0] * (D + 1)  # vals[0] = 0
    s_range = range(1, L + 1)
    p_range = range(1, L + 1)
    w_size = stride * stride

    # Evaluate F(x) at x = 1..D.
    for x in range(1, D + 1):
        z = (x + 1) % P

        # coef[s] = z^{C(s,2)} / s!
        coef = [0] * (L + 1)
        zpow_c = 1
        add_pow = 1
        for s in s_range:
            zpow_c = (zpow_c * add_pow) % P
            coef[s] = (zpow_c * invfact[s]) % P
            add_pow = (add_pow * z) % P

        # w[p, s] = z^{C(s,2)} * (z^p - 1)^s / s!
        w = [0] * w_size
        zp = 1
        for p in p_range:
            zp = (zp * z) % P
            base_val = zp - 1
            if base_val < 0:
                base_val += P
            if base_val == 0:
                continue
            pow_base = 1
            base_idx = p * stride
            for s in s_range:
                pow_base = (pow_base * base_val) % P
                w[base_idx + s] = (pow_base * coef[s]) % P

        dp = [0] * S
        dp[init_idx] = 1

        dp_list = dp
        w_list = w
        trans_list = trans
        P_local = P

        for idx in order:
            val = dp_list[idx]
            if val:
                if val >= P_local:
                    val %= P_local
                if val:
                    for t, off in trans_list[idx]:
                        dp_list[t] += val * w_list[off]

        ssum = 0
        for fi in final_indices:
            ssum += dp_list[fi]

        vals[x] = (ssum % P) * fact_nm1 % P

    # Interpolate vals[0..D] into power basis.
    # Newton forward form: F(x) = sum c[k] * C(x, k), c[k] = Δ^k F(0).
    diff = vals[:]
    c = [0] * (D + 1)
    for k in range(D + 1):
        c[k] = diff[0]
        for i in range(D - k):
            diff[i] = (diff[i + 1] - diff[i]) % P

    inv = [0] * (D + 1)
    if D >= 1:
        inv[1] = 1
        for i in range(2, D + 1):
            inv[i] = (P - (P // i)) * inv[P % i] % P

    ans = [0] * (D + 1)
    row = [1]  # coefficients of C(x, 0)
    ans[0] = c[0]

    for k in range(1, D + 1):
        km1 = k - 1
        invk = inv[k]
        new = [0] * (k + 1)

        if km1:
            new[0] = (-km1 * row[0]) % P
        else:
            new[0] = 0
        new[0] = (new[0] * invk) % P

        for m in range(1, k):
            new[m] = (row[m - 1] - km1 * row[m]) % P
            new[m] = (new[m] * invk) % P

        new[k] = (row[k - 1] * invk) % P
        row = new

        ck = c[k]
        if ck:
            for m in range(k + 1):
                ans[m] += ck * row[m]

    for i in range(D + 1):
        ans[i] %= P

    out = []
    for M in range(N - 1, total_edges + 1):
        if M <= D:
            out.append(str(ans[M]))
        else:
            out.append("0")

    sys.stdout.write(" ".join(out) + "\n")


if __name__ == "__main__":
    solve()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, p = data[0], data[1]
    vals = data[2:]
    A = [vals[i * n:(i + 1) * n] for i in range(n)]

    if p == 2:
        v = str(n & 1)
        line = " ".join([v] * n)
        sys.stdout.write("\n".join([line] * n))
        return

    K = 0
    for row in A:
        K += row.count(0)

    rn = range(n)
    m1 = p - 1

    def mat_mul(A, B, mod=p, n=n, rn=rn, m1=m1):
        C = [None] * n
        for i in rn:
            Ci = [0] * n
            Ai = A[i]
            for k in rn:
                aik = Ai[k]
                if aik:
                    Bk = B[k]
                    if aik == 1:
                        for j in rn:
                            Ci[j] += Bk[j]
                    elif aik == m1:
                        for j in rn:
                            Ci[j] -= Bk[j]
                    else:
                        for j in rn:
                            Ci[j] += aik * Bk[j]
            C[i] = [x % mod for x in Ci]
        return C

    res = A
    base = A
    e = p - 1
    while e:
        if e & 1:
            res = mat_mul(res, base)
        e >>= 1
        if e:
            base = mat_mul(base, base)

    M = res

    for i in rn:
        if A[i][i] == 0:
            Ai = A[i]
            Mi = M[i]
            for j in rn:
                if j == i:
                    continue

                val = Ai[j]
                if val:
                    x = Mi[j] + val
                    if x >= p:
                        x -= p
                    Mi[j] = x

                val = A[j][i]
                if val:
                    x = M[j][i] + val
                    if x >= p:
                        x -= p
                    M[j][i] = x

    if p == 3:
        for i in rn:
            Ai = A[i]
            Mi = M[i]
            for j in rn:
                if i != j and Ai[j] == 0:
                    val = A[j][i]
                    if val:
                        x = Mi[j] + val
                        if x >= p:
                            x -= p
                        Mi[j] = x

    if K & 1:
        for i in rn:
            Mi = M[i]
            for j in rn:
                if Mi[j]:
                    Mi[j] = p - Mi[j]

    sys.stdout.write("\n".join(" ".join(map(str, row)) for row in M))

if __name__ == "__main__":
    solve()

import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    M = next(it)
    A = next(it)
    B = next(it)

    intervals = []
    for _ in range(M):
        L = next(it)
        R = next(it)
        if intervals and L <= intervals[-1][1] + 1:
            if R > intervals[-1][1]:
                intervals[-1][1] = R
        else:
            intervals.append([L, R])

    K = len(intervals)

    # A bad block of length at least B cannot be jumped over.
    for L, R in intervals:
        if R - L + 1 >= B:
            print("No")
            return

    cand = [1, N]
    for L, R in intervals:
        s = L - B
        if s < 1:
            s = 1
        cand.extend(range(s, L))  # s .. L-1
        s = R + 1
        e = R + B
        if e > N:
            e = N
        cand.extend(range(s, e + 1))  # s .. e

    cand.sort()
    crit = []
    seg_id = []
    idx = 0
    prev = None
    for x in cand:
        if x == prev:
            continue
        prev = x
        while idx < K and intervals[idx][1] < x:
            idx += 1
        if idx < K and intervals[idx][0] <= x <= intervals[idx][1]:
            continue
        crit.append(x)
        seg_id.append(idx)

    if not crit or crit[0] != 1:
        print("No")
        return
    if N == 1:
        print("Yes")
        return

    recent = deque([crit[0]])
    ans = False

    if A == B:
        seg_mask = [0] * (K + 1)
        seg_mask[seg_id[0]] = 1 << (crit[0] % A)
        for i in range(1, len(crit)):
            x = crit[i]
            while recent and x - recent[0] > B:
                recent.popleft()
            ok = False
            if recent and x - recent[0] >= A:
                ok = True
            else:
                seg = seg_id[i]
                if seg_mask[seg] & (1 << (x % A)):
                    ok = True
            if ok:
                if x == N:
                    ans = True
                recent.append(x)
                seg = seg_id[i]
                seg_mask[seg] |= 1 << (x % A)
    else:
        if A == 1:
            T = 1
        else:
            diff = B - A
            k0 = (A - 1 + diff - 1) // diff
            T = k0 * A
        table = [False] * (T + 1)
        for d in range(1, T):
            table[d] = (d + B - 1) // B <= d // A

        seg_reach = [[] for _ in range(K + 1)]
        seg_reach[seg_id[0]].append(crit[0])

        for i in range(1, len(crit)):
            x = crit[i]
            while recent and x - recent[0] > B:
                recent.popleft()
            ok = False
            if recent and x - recent[0] >= A:
                ok = True
            else:
                seg = seg_id[i]
                lst = seg_reach[seg]
                if lst:
                    if x - lst[0] >= T:
                        ok = True
                    else:
                        for u in lst:
                            d = x - u
                            if d < A:
                                break
                            if table[d]:
                                ok = True
                                break
            if ok:
                if x == N:
                    ans = True
                recent.append(x)
                seg_reach[seg_id[i]].append(x)

    print("Yes" if ans else "No")

