class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 1:
            return 1

        bits = [ord(c) - 48 for c in s]

        # Original maximum run length. Zero flips always achieves this.
        max_run = 1
        cur = 1
        for i in range(1, n):
            if bits[i] == bits[i - 1]:
                cur += 1
            else:
                cur = 1
            if cur > max_run:
                max_run = cur

        if numOps == 0:
            return max_run

        # Minimum flips to make the string strictly alternating.
        # Pattern 0101... has mismatches mism0; pattern 1010... has n - mism0.
        mism0 = 0
        for i, b in enumerate(bits):
            if b != (i & 1):
                mism0 += 1
        if min(mism0, n - mism0) <= numOps:
            return 1

        limit = numOps
        INF = limit + 1

        def feasible(L: int) -> bool:
            # The original string already has max run <= L.
            if L >= max_run:
                return True

            # Max run 1 means strictly alternating.
            if L == 1:
                return min(mism0, n - mism0) <= limit

            # dp0[r] = min flips for processed prefix ending in bit 0
            #          with current run length r.
            # dp1[r] = same for ending in bit 1.
            dp0 = [INF] * (L + 1)
            dp1 = [INF] * (L + 1)

            first = bits[0]
            if first == 0:
                dp0[1] = 0
                if limit >= 1:
                    dp1[1] = 1
            else:
                dp1[1] = 0
                if limit >= 1:
                    dp0[1] = 1

            for i in range(1, n):
                bit = bits[i]
                ndp0 = [INF] * (L + 1)
                ndp1 = [INF] * (L + 1)

                if bit == 0:
                    # Original bit is 0.
                    # From last 0: keep 0 costs 0, switch to 1 costs 1.
                    # From last 1: keep 1 costs 1, switch to 0 costs 0.
                    for r in range(1, L + 1):
                        c0 = dp0[r]
                        if c0 <= limit:
                            if r < L and c0 < ndp0[r + 1]:
                                ndp0[r + 1] = c0
                            nc = c0 + 1
                            if nc <= limit and nc < ndp1[1]:
                                ndp1[1] = nc

                        c1 = dp1[r]
                        if c1 <= limit:
                            if r < L:
                                nc = c1 + 1
                                if nc <= limit and nc < ndp1[r + 1]:
                                    ndp1[r + 1] = nc
                            if c1 < ndp0[1]:
                                ndp0[1] = c1
                else:
                    # Original bit is 1.
                    # From last 0: keep 0 costs 1, switch to 1 costs 0.
                    # From last 1: keep 1 costs 0, switch to 0 costs 1.
                    for r in range(1, L + 1):
                        c0 = dp0[r]
                        if c0 <= limit:
                            if r < L:
                                nc = c0 + 1
                                if nc <= limit and nc < ndp0[r + 1]:
                                    ndp0[r + 1] = nc
                            if c0 < ndp1[1]:
                                ndp1[1] = c0

                        c1 = dp1[r]
                        if c1 <= limit:
                            if r < L and c1 < ndp1[r + 1]:
                                ndp1[r + 1] = c1
                            nc = c1 + 1
                            if nc <= limit and nc < ndp0[1]:
                                ndp0[1] = nc

                dp0, dp1 = ndp0, ndp1

            for r in range(1, L + 1):
                if dp0[r] <= limit or dp1[r] <= limit:
                    return True
            return False

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo


def _brute_all(s: str):
    n = len(s)
    bits = [ord(c) - 48 for c in s]
    size = 1 << n

    pop = [0] * size
    for m in range(1, size):
        pop[m] = pop[m >> 1] + (m & 1)

    best_exact = [n] * size
    for mask in range(size):
        cost = pop[mask]
        prev = -1
        cur = 0
        local = 0

        for i in range(n):
            b = bits[i] ^ ((mask >> i) & 1)
            if b == prev:
                cur += 1
            else:
                prev = b
                cur = 1
            if cur > local:
                local = cur

        if local < best_exact[cost]:
            best_exact[cost] = local

    res = []
    best = n
    for k in range(n + 1):
        if best_exact[k] < best:
            best = best_exact[k]
        res.append(best)
    return res


def _run_tests():
    sol = Solution()

    examples = [
        ("000001", 1, 2),
        ("0000", 2, 1),
        ("0101", 0, 1),
    ]
    for s, k, expected in examples:
        got = sol.minLength(s, k)
        assert got == expected, f"example failed: s={s}, numOps={k}, got={got}, expected={expected}"

    # Large sanity checks.
    assert sol.minLength("0" * 1000, 0) == 1000
    assert sol.minLength("0" * 1000, 1000) == 1
    assert sol.minLength("0" * 1000, 500) == 1
    assert sol.minLength("0" * 1000, 499) == 2
    assert sol.minLength("0" * 999, 499) == 1

    # Exhaustive brute-force validation for small lengths.
    for n in range(1, 9):
        for mask in range(1 << n):
            s = "".join("1" if (mask >> i) & 1 else "0" for i in range(n))
            expected = _brute_all(s)
            for k in range(n + 1):
                got = sol.minLength(s, k)
                if got != expected[k]:
                    raise AssertionError(
                        f"brute mismatch: n={n}, s={s}, numOps={k}, got={got}, expected={expected[k]}"
                    )


if __name__ == "__main__":
    _run_tests()

import sys
from bisect import bisect_right


def merge_intervals(d):
    for ivs in d.values():
        if len(ivs) > 1:
            ivs.sort()
            w = 0
            cl, cr = ivs[0]
            for i in range(1, len(ivs)):
                l, r = ivs[i]
                if l <= cr:
                    if r > cr:
                        cr = r
                else:
                    ivs[w] = (cl, cr)
                    w += 1
                    cl, cr = l, r
            ivs[w] = (cl, cr)
            del ivs[w + 1:]


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    idx = 0
    N = int(data[idx])
    M = int(data[idx + 1])
    sx = int(data[idx + 2])
    sy = int(data[idx + 3])
    idx += 4

    houses = []
    house_ys = set()
    house_xs = set()

    for _ in range(N):
        x = int(data[idx])
        y = int(data[idx + 1])
        idx += 2
        houses.append((x, y))
        house_ys.add(y)
        house_xs.add(x)

    x = sx
    y = sy
    horiz = {}
    vert = {}

    for _ in range(M):
        d = data[idx]
        c = int(data[idx + 1])
        idx += 2

        if d == b'U':
            ny = y + c
            if x in house_xs:
                lst = vert.get(x)
                if lst is None:
                    vert[x] = [(y, ny)]
                else:
                    lst.append((y, ny))
            y = ny
        elif d == b'D':
            ny = y - c
            if x in house_xs:
                lst = vert.get(x)
                if lst is None:
                    vert[x] = [(ny, y)]
                else:
                    lst.append((ny, y))
            y = ny
        elif d == b'L':
            nx = x - c
            if y in house_ys:
                lst = horiz.get(y)
                if lst is None:
                    horiz[y] = [(nx, x)]
                else:
                    lst.append((nx, x))
            x = nx
        else:  # R
            nx = x + c
            if y in house_ys:
                lst = horiz.get(y)
                if lst is None:
                    horiz[y] = [(x, nx)]
                else:
                    lst.append((x, nx))
            x = nx

    del data
    del house_ys, house_xs

    merge_intervals(horiz)
    merge_intervals(vert)

    INF = 10 ** 30
    br = bisect_right
    hget = horiz.get
    vget = vert.get
    ans = 0

    for hx, hy in houses:
        ivs = hget(hy)
        if ivs is not None:
            if len(ivs) == 1:
                l, r = ivs[0]
                if l <= hx <= r:
                    ans += 1
                    continue
            else:
                i = br(ivs, (hx, INF)) - 1
                if i >= 0 and ivs[i][1] >= hx:
                    ans += 1
                    continue

        ivs = vget(hx)
        if ivs is not None:
            if len(ivs) == 1:
                l, r = ivs[0]
                if l <= hy <= r:
                    ans += 1
                    continue
            else:
                i = br(ivs, (hy, INF)) - 1
                if i >= 0 and ivs[i][1] >= hy:
                    ans += 1

    sys.stdout.write(f"{x} {y} {ans}\n")


if __name__ == "__main__":
    main()

import random

INF = 10**9


class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        n = len(s)
        ans = n - max(cnt)
        if ans == 0:
            return 0

        for k in range(1, 2 * n + 1):
            if k - n >= ans:
                break

            dp0 = cnt[0]
            dp1 = cnt[0] - k
            if dp1 < 0:
                dp1 = -dp1

            for i in range(1, 26):
                prev = cnt[i - 1]
                cur = cnt[i]

                best = dp0 if dp0 < dp1 else dp1
                ndp0 = best + cur

                cost1 = cur - k
                if cost1 < 0:
                    cost1 = -cost1

                deficit = k - cur
                if deficit > 0:
                    save0 = prev if prev < deficit else deficit
                    surplus1 = prev - k
                    if surplus1 > 0:
                        save1 = surplus1 if surplus1 < deficit else deficit
                    else:
                        save1 = 0
                else:
                    save0 = 0
                    save1 = 0

                v0 = dp0 + cost1 - save0
                v1 = dp1 + cost1 - save1
                ndp1 = v0 if v0 < v1 else v1

                dp0, dp1 = ndp0, ndp1

            cur_cost = dp0 if dp0 < dp1 else dp1
            if cur_cost < ans:
                ans = cur_cost
                if ans == 0:
                    return 0

        return ans


def min_cost_formula(b):
    """Closed-form exact cost for a fixed source/target difference vector b."""
    total = 0
    for v in b:
        total += v if v >= 0 else -v

    save = 0
    for i in range(25):
        surplus = b[i] if b[i] > 0 else 0
        deficit = -b[i + 1] if b[i + 1] < 0 else 0
        save += surplus if surplus < deficit else deficit

    return total - save


def min_cost_flow_line(b, n, cutoff=INF):
    """
    Exact min-cost flow DP on the 26-letter line.

    b[i] = source_count[i] - target_count[i].
    Let x_i be flow from letter i to i+1, with x_{-1}=x_{25}=0.
    Cost = sum_i x_i + |b[i] + x_{i-1} - x_i|.
    """
    if cutoff <= 0:
        return INF

    total_pos = 0
    for v in b:
        if v > 0:
            total_pos += v

    B = min(n, total_pos)
    if B == 0:
        cost = 0
        for v in b:
            cost += v if v >= 0 else -v
        return cost if cost < cutoff else INF

    dp = [INF] * (B + 1)
    dp[0] = 0

    for i in range(26):
        t = b[i]

        if i < 25:
            # suffix[p] = min_{px >= p} dp[px] + t + px
            suffix = [INF] * (B + 2)
            for px in range(B, -1, -1):
                val = dp[px]
                if val < cutoff:
                    cand = val + t + px
                    suffix[px] = cand if cand < suffix[px + 1] else suffix[px + 1]
                else:
                    suffix[px] = suffix[px + 1]

            # prefix[p] = min_{px < p} dp[px] - t - px
            prefix = [INF] * (B + 2)
            for px in range(B + 1):
                val = dp[px]
                if val < cutoff:
                    cand = val - t - px
                    prefix[px + 1] = cand if cand < prefix[px] else prefix[px]
                else:
                    prefix[px + 1] = prefix[px]

            ndp = [INF] * (B + 1)
            for x in range(B + 1):
                p = x - t
                best_val = INF

                if p <= 0:
                    best_val = suffix[0]
                elif p > B + 1:
                    if prefix[B + 1] < INF:
                        best_val = 2 * x + prefix[B + 1]
                else:
                    best_val = suffix[p]
                    if prefix[p] < INF:
                        cand = 2 * x + prefix[p]
                        if cand < best_val:
                            best_val = cand

                if best_val < cutoff:
                    ndp[x] = best_val

            dp = ndp
        else:
            # Final letter: x_25 must be 0.
            best_val = INF
            for px, val in enumerate(dp):
                if val >= cutoff:
                    continue
                diff = t + px
                if diff < 0:
                    diff = -diff
                v = val + diff
                if v < best_val and v < cutoff:
                    best_val = v
            dp = [best_val]

    return dp[0]


def brute_force(s):
    """
    Exhaustive brute force for small strings.

    Enumerates all good targets over a safe relevant alphabet:
    all letters that appear, plus their immediate next letter.
    A zero-count letter whose previous letter also has zero count can never
    be part of an optimal target, because removing it strictly reduces cost.
    """
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1

    n = len(s)
    best = n - max(cnt)
    if best == 0:
        return 0

    pos = [i for i, c in enumerate(cnt) if c > 0]
    rel = set(pos)
    for i in pos:
        if i + 1 < 26:
            rel.add(i + 1)
    rel = sorted(rel)
    r = len(rel)

    masks_by_m = [[] for _ in range(r + 1)]
    for mask in range(1 << r):
        if mask == 0:
            continue
        inds = []
        m = 0
        for j, idx in enumerate(rel):
            if mask & (1 << j):
                m += 1
                inds.append(idx)
        masks_by_m[m].append(tuple(inds))

    for k in range(1, 2 * n + 1):
        if k - n >= best:
            break

        for m in range(1, r + 1):
            length = m * k
            if abs(length - n) >= best:
                continue

            for inds in masks_by_m[m]:
                if abs(length - n) >= best:
                    continue

                b = cnt[:]
                for idx in inds:
                    b[idx] -= k

                cost = min_cost_flow_line(b, n, best)
                if cost < best:
                    best = cost
                    if best == 0:
                        return 0

    return best


def validate_flow():
    """Cross-check the line-flow DP against the closed-form formula."""
    random.seed(777)
    for _ in range(200):
        b = [random.randint(-3, 3) for _ in range(26)]
        n_val = sum(v for v in b if v > 0)
        c1 = min_cost_flow_line(b, n_val, INF)
        c2 = min_cost_formula(b)
        if c1 != c2:
            return False, f"b={b} line={c1} formula={c2}"
    return True, ""


def run_tests():
    sol = Solution()
    failures = []
    bf_cache = {}

    def get_bf(s):
        if s not in bf_cache:
            bf_cache[s] = brute_force(s)
        return bf_cache[s]

    examples = [
        ("acab", 1),
        ("wddw", 0),
        ("aaabc", 2),
    ]

    for s, expected in examples:
        sol_ans = sol.makeStringGood(s)
        bf_ans = get_bf(s)
        if sol_ans != expected or sol_ans != bf_ans:
            failures.append((s, expected, sol_ans, bf_ans))

    edge_cases = [
        "aaa",
        "aaaa",
        "zzzz",
        "zzzzz",
        "abc",
        "abcd",
        "abcde",
        "abcdef",
        "yzz",
        "zzza",
        "yzzz",
        "xzyz",
        "zzzy",
        "xzyzz",
        "yzza",
        "yzyz",
        "aaaccc",
        "abbbc",
        "aaabc",
        "acab",
        "wddw",
    ]

    random.seed(12345)
    random_cases = []

    for _ in range(120):
        n = random.randint(3, 5)
        alpha = random.choice([
            "abcde",
            "abcxyz",
            "abcdefghijklmnopqrstuvwxyz",
        ])
        random_cases.append("".join(random.choice(alpha) for _ in range(n)))

    for _ in range(40):
        n = random.randint(3, 5)
        random_cases.append("".join(random.choice("xyz") for _ in range(n)))

    for s in edge_cases + random_cases:
        sol_ans = sol.makeStringGood(s)
        bf_ans = get_bf(s)
        if sol_ans != bf_ans:
            failures.append((s, bf_ans, sol_ans, bf_ans))

    flow_ok, flow_msg = validate_flow()
    if not flow_ok:
        failures.append(("flow_validation", flow_msg, None, None))

    print("SAMPLE TESTS:", "FAIL" if failures else "PASS")
    if failures:
        for f in failures[:20]:
            print("FAIL", f)
    else:
        print("Examples: acab=1, wddw=0, aaabc=2")
        print(f"Checked {len(bf_cache)} unique strings against brute force; no failing cases.")


if __name__ == "__main__":
    run_tests()

import sys
import math
from bisect import bisect_right


def make_blocks(arr, S):
    blocks = []
    n = len(arr)
    for start in range(0, n, S):
        seg = arr[start:start + S]
        L = len(seg)
        sv = sorted(seg)
        pref = [0] * (L + 1)
        s = 0
        for i, v in enumerate(sv):
            s += v
            pref[i + 1] = s
        blocks.append((seg, sv, pref, s, L))
    return blocks


def prefix_contrib(seq, osv, opref, otot, olen, C):
    """C[r] = sum over first r elements of seq vs the whole other block."""
    s = 0
    C[0] = 0
    br = bisect_right
    i = 1
    for val in seq:
        p = br(osv, val)
        op = opref[p]
        s += val * p - op + (otot - op) - val * (olen - p)
        C[i] = s
        i += 1
    return s


def full_contrib(seq, osv, opref, otot, olen):
    """Sum over all elements of seq vs the whole other block."""
    s = 0
    br = bisect_right
    for val in seq:
        p = br(osv, val)
        op = opref[p]
        s += val * p - op + (otot - op) - val * (olen - p)
    return s


def sum_abs_sorted(l1, t1, l2, t2):
    """Sum |x-y| over two sorted lists, using a two-pointer scan."""
    if len(l1) <= len(l2):
        it = l1
        other = l2
        total = t2
    else:
        it = l2
        other = l1
        total = t1

    p = 0
    sum_le = 0
    lo = len(other)
    s = 0
    for val in it:
        while p < lo and other[p] <= val:
            sum_le += other[p]
            p += 1
        s += val * p - sum_le + (total - sum_le) - val * (lo - p)
    return s


def process_light(qs, Aseg, Bseg, Alen, Blen, Asv, Atot, Bsv, Btot, ans, S):
    DIRECT = max(2000, S)
    use_cache = (S <= 3000) or (len(qs) * S <= 2_000_000)
    cacheA = {} if use_cache else None
    cacheB = {} if use_cache else None

    for q, ra, rb in qs:
        if ra * rb <= DIRECT:
            s = 0
            if ra <= rb:
                for i in range(ra):
                    av = Aseg[i]
                    for j in range(rb):
                        bv = Bseg[j]
                        if av >= bv:
                            s += av - bv
                        else:
                            s += bv - av
            else:
                for j in range(rb):
                    bv = Bseg[j]
                    for i in range(ra):
                        av = Aseg[i]
                        if av >= bv:
                            s += av - bv
                        else:
                            s += bv - av
            ans[q] += s
            continue

        if use_cache:
            item = cacheA.get(ra)
            if item is None:
                if ra == Alen:
                    item = (Asv, Atot)
                else:
                    lst = Aseg[:ra]
                    lst.sort()
                    item = (lst, sum(lst))
                cacheA[ra] = item

            item2 = cacheB.get(rb)
            if item2 is None:
                if rb == Blen:
                    item2 = (Bsv, Btot)
                else:
                    lst = Bseg[:rb]
                    lst.sort()
                    item2 = (lst, sum(lst))
                cacheB[rb] = item2
        else:
            if ra == Alen:
                l1 = Asv
                t1 = Atot
            else:
                l1 = Aseg[:ra]
                l1.sort()
                t1 = sum(l1)

            if rb == Blen:
                l2 = Bsv
                t2 = Btot
            else:
                l2 = Bseg[:rb]
                l2.sort()
                t2 = sum(l2)

            item = (l1, t1)
            item2 = (l2, t2)

        ans[q] += sum_abs_sorted(item[0], item[1], item2[0], item2[1])


def process_heavy(qs, Aseg, Bseg, Alen, Blen, ans):
    max_ra = 0
    max_rb = 0
    for _, ra, rb in qs:
        if ra > max_ra:
            max_ra = ra
        if rb > max_rb:
            max_rb = rb

    if max_ra * Blen <= max_rb * Alen:
        by_ra = {}
        for q, ra, rb in qs:
            lst = by_ra.get(ra)
            if lst is None:
                by_ra[ra] = [(q, rb)]
            else:
                lst.append((q, rb))

        prev = [0] * (Blen + 1)
        new = [0] * (Blen + 1)
        cur = 0

        for target in sorted(by_ra):
            while cur < target:
                x = Aseg[cur]
                s = 0
                new[0] = 0
                for j in range(Blen):
                    y = Bseg[j]
                    if x >= y:
                        s += x - y
                    else:
                        s += y - x
                    new[j + 1] = prev[j + 1] + s
                prev, new = new, prev
                cur += 1

            for q, rb in by_ra[target]:
                ans[q] += prev[rb]
    else:
        by_rb = {}
        for q, ra, rb in qs:
            lst = by_rb.get(rb)
            if lst is None:
                by_rb[rb] = [(q, ra)]
            else:
                lst.append((q, ra))

        prev = [0] * (Alen + 1)
        new = [0] * (Alen + 1)
        cur = 0

        for target in sorted(by_rb):
            while cur < target:
                y = Bseg[cur]
                s = 0
                new[0] = 0
                for i in range(Alen):
                    x = Aseg[i]
                    if x >= y:
                        s += x - y
                    else:
                        s += y - x
                    new[i + 1] = prev[i + 1] + s
                prev, new = new, prev
                cur += 1

            for q, ra in by_rb[target]:
                ans[q] += prev[ra]


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    pos = 0
    N = data[pos]
    pos += 1

    A = data[pos:pos + N]
    pos += N

    B = data[pos:pos + N]
    pos += N

    K = data[pos]
    pos += 1

    # Tuned block size for Python: same sqrt idea, slightly larger than 1.2*N/sqrt(K).
    S = int(1.8 * N / math.sqrt(K))
    if S < 1:
        S = 1
    if S > N:
        S = N

    NA = (N + S - 1) // S
    NB = (N + S - 1) // S

    groupsA = [[] for _ in range(NA)]
    groupsB = [[] for _ in range(NB)]
    res_groups = {}
    fa_arr = [0] * K
    fb_arr = [0] * K

    max_fa_full = 0
    max_fb_full = 0

    for q in range(K):
        x = data[pos]
        y = data[pos + 1]
        pos += 2

        fa = x // S
        ra = x - fa * S
        fb = y // S
        rb = y - fb * S

        fa_arr[q] = fa
        fb_arr[q] = fb

        if fa > max_fa_full:
            max_fa_full = fa
        if fb > max_fb_full:
            max_fb_full = fb

        if ra:
            groupsA[fa].append((q, ra, fb))
        if rb:
            groupsB[fb].append((q, rb, fa))
        if ra and rb:
            key = (fa, fb)
            if key in res_groups:
                res_groups[key].append((q, ra, rb))
            else:
                res_groups[key] = [(q, ra, rb)]

    del data

    A_blocks = make_blocks(A, S)
    B_blocks = make_blocks(B, S)
    del A, B

    ans = [0] * K

    # Sweep A blocks:
    # - compute full block-pair sums F[a][b]
    # - add partial-A-prefix vs full-B-block contributions
    F = [[0] * max_fb_full for _ in range(max_fa_full)]

    for a in range(max_fa_full):
        Aseg, Asv, Apref, Atot, Alen = A_blocks[a]
        rowF = F[a]
        qs = groupsA[a]

        if qs:
            max_fb_q = 0
            for _, _, fb in qs:
                if fb > max_fb_q:
                    max_fb_q = fb

            if max_fb_q:
                C = [0] * (Alen + 1)
                for b in range(max_fb_q):
                    _, Bsv, Bpref, Btot, Blen = B_blocks[b]
                    s = prefix_contrib(Aseg, Bsv, Bpref, Btot, Blen, C)
                    rowF[b] = s
                    for q, ra, fb in qs:
                        if fb > b:
                            ans[q] += C[ra]

            for b in range(max_fb_q, max_fb_full):
                _, Bsv, Bpref, Btot, Blen = B_blocks[b]
                rowF[b] = full_contrib(Aseg, Bsv, Bpref, Btot, Blen)
        else:
            for b in range(max_fb_full):
                _, Bsv, Bpref, Btot, Blen = B_blocks[b]
                rowF[b] = full_contrib(Aseg, Bsv, Bpref, Btot, Blen)

    # If the maximum full-A count is not the last block, a query may still have
    # a partial prefix in that last full-count block.
    if max_fa_full < NA:
        qs = groupsA[max_fa_full]
        if qs:
            Aseg, Asv, Apref, Atot, Alen = A_blocks[max_fa_full]
            max_fb_q = 0
            for _, _, fb in qs:
                if fb > max_fb_q:
                    max_fb_q = fb

            if max_fb_q:
                C = [0] * (Alen + 1)
                for b in range(max_fb_q):
                    _, Bsv, Bpref, Btot, Blen = B_blocks[b]
                    prefix_contrib(Aseg, Bsv, Bpref, Btot, Blen, C)
                    for q, ra, fb in qs:
                        if fb > b:
                            ans[q] += C[ra]

    # 2D prefix over full block-pair sums.
    prefFF = [[0] * (max_fb_full + 1) for _ in range(max_fa_full + 1)]
    for a in range(max_fa_full):
        row = F[a]
        acc = 0
        prev = prefFF[a]
        cur = prefFF[a + 1]
        for b in range(max_fb_full):
            acc += row[b]
            cur[b + 1] = prev[b + 1] + acc

    for q in range(K):
        ans[q] += prefFF[fa_arr[q]][fb_arr[q]]

    # Sweep B blocks:
    # - add full-A-blocks vs partial-B-prefix contributions
    for b in range(max_fb_full):
        qs = groupsB[b]
        if not qs:
            continue

        Bseg, Bsv, Bpref, Btot, Blen = B_blocks[b]
        max_fa_q = 0
        for _, _, fa in qs:
            if fa > max_fa_q:
                max_fa_q = fa

        if max_fa_q:
            C = [0] * (Blen + 1)
            for a in range(max_fa_q):
                Aseg, Asv, Apref, Atot, Alen = A_blocks[a]
                prefix_contrib(Bseg, Asv, Apref, Atot, Alen, C)
                for q, rb, fa in qs:
                    if fa > a:
                        ans[q] += C[rb]

    if max_fb_full < NB:
        qs = groupsB[max_fb_full]
        if qs:
            Bseg, Bsv, Bpref, Btot, Blen = B_blocks[max_fb_full]
            max_fa_q = 0
            for _, _, fa in qs:
                if fa > max_fa_q:
                    max_fa_q = fa

            if max_fa_q:
                C = [0] * (Blen + 1)
                for a in range(max_fa_q):
                    Aseg, Asv, Apref, Atot, Alen = A_blocks[a]
                    prefix_contrib(Bseg, Asv, Apref, Atot, Alen, C)
                    for q, rb, fa in qs:
                        if fa > a:
                            ans[q] += C[rb]

    # Partial-partial residuals, grouped by block pair.
    for (a, b), qs in res_groups.items():
        Aseg, Asv, Apref, Atot, Alen = A_blocks[a]
        Bseg, Bsv, Bpref, Btot, Blen = B_blocks[b]

        max_ra = 0
        max_rb = 0
        light_cost = 0
        for _, ra, rb in qs:
            if ra > max_ra:
                max_ra = ra
            if rb > max_rb:
                max_rb = rb
            light_cost += ra + rb

        heavy_cost = max_ra * Blen
        alt_cost = max_rb * Alen
        if alt_cost < heavy_cost:
            heavy_cost = alt_cost

        if len(qs) >= 300 and heavy_cost <= 4_000_000 and heavy_cost * 2 < light_cost:
            process_heavy(qs, Aseg, Bseg, Alen, Blen, ans)
        else:
            process_light(qs, Aseg, Bseg, Alen, Blen, Asv, Atot, Bsv, Btot, ans, S)

    sys.stdout.write("\n".join(map(str, ans)))


if __name__ == "__main__":
    main()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:1 + n]
    del data

    total = sum(a)
    max_a = max(a)
    max_sum = max_a * 2

    # V_0 = sum_{i <= j} (A_i + A_j) = (N + 1) * sum(A)
    ans = (n + 1) * total

    # Dense arrays are faster for small moduli.
    LIMIT = 1 << 20
    m = 2

    while m <= max_sum:
        mask = m - 1

        if m <= LIMIT:
            cnt = [0] * m
            sm = [0] * m
            touched = []
            append = touched.append

            for x in a:
                r = x & mask
                c = cnt[r]
                if c:
                    cnt[r] = c + 1
                    sm[r] = sm[r] + x
                else:
                    append(r)
                    cnt[r] = 1
                    sm[r] = x

            vt = 0
            for r in touched:
                cr = cnt[r]
                sr = sm[r]
                s = (-r) & mask

                if s == r:
                    vt += (cr + 1) * sr // m
                elif r < s:
                    cs = cnt[s]
                    if cs:
                        vt += (cr * sm[s] + cs * sr) // m

            ans -= vt

        else:
            cnt = {}
            sm = {}
            cnt_get = cnt.get

            for x in a:
                r = x & mask
                c = cnt_get(r, 0)
                if c:
                    cnt[r] = c + 1
                    sm[r] = sm[r] + x
                else:
                    cnt[r] = 1
                    sm[r] = x

            vt = 0
            for r, cr in cnt.items():
                sr = sm[r]
                s = (-r) & mask

                if s == r:
                    vt += (cr + 1) * sr // m
                elif r < s:
                    cs = cnt_get(s, 0)
                    if cs:
                        vt += (cr * sm[s] + cs * sr) // m

            ans -= vt

        m <<= 1

    print(ans)

